//! VL53L1X time-of-flight driver, generic over `embedded-hal-async` I2C.
//!
//! Port of Pololu's `vl53l1x-arduino` (low-power-autonomous ranging).
//! Nothing here depends on esp-hal: pass any `embedded_hal_async::i2c::I2c`
//! (including a shared-bus `I2cDevice`) and an XSHUT pin, or `NoXshut` if the
//! pin isn't wired.
//!
//! Expects a sibling `regAddr` module at the crate root with the register
//! constants (`u16`), plus `Target_Rate: u16` and `Timing_Guard: u32`.

use embassy_time::{Duration, Instant, Timer};
use embedded_hal::digital::{ErrorType as PinErrorType, OutputPin};
use embedded_hal_async::i2c::{ErrorType as I2cErrorType, I2c};

use crate::regAddr as reg;

pub const DEFAULT_ADDRESS: u8 = 0x29;
const MODEL_ID: u16 = 0xEACC;
#[derive(Clone, Copy)]
pub enum DistanceMode {
    Short,
    Medium,
    Long,
}

type Res<T, B> = Result<T, Error<<B as I2cErrorType>::Error>>;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Error<E> {
    /// The I2C bus returned an error (NACK, bus fault, ...).
    I2c(E),
    /// The XSHUT pin failed to change state.
    Pin,
    /// The chip answered, but its model ID isn't a VL53L1X (value read is inside).
    WrongDevice(u16),
    /// Waited longer than the configured IO timeout.
    Timeout,
    /// A parameter was out of range (e.g. timing budget).
    InvalidArgument,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RangeStatus {
    RangeValid = 0,
    /// Sigma estimator check is above the internal threshold.
    SigmaFail = 1,
    /// Signal value is below the internal threshold.
    SignalFail = 2,
    /// Target is below minimum detection threshold, but the range is valid.
    RangeValidMinRangeClipped = 3,
    /// Phase is out of bounds (nothing detected; try a longer distance mode).
    OutOfBoundsFail = 4,
    /// Hardware or VCSEL failure.
    HardwareFail = 5,
    /// Range is valid but the wraparound check hasn't been done (first sample).
    RangeValidNoWrapCheckFail = 6,
    /// Wrapped target, phases don't match.
    WrapTargetFail = 7,
    XtalkSignalFail = 9,
    SynchronizationInt = 10,
    /// Target is below minimum detection threshold.
    MinRangeFail = 13,
    None = 255,
}

impl RangeStatus {
    /// True for the statuses that carry a usable distance.
    pub fn is_valid(self) -> bool {
        matches!(
            self,
            RangeStatus::RangeValid
                | RangeStatus::RangeValidMinRangeClipped
                | RangeStatus::RangeValidNoWrapCheckFail
        )
    }

    pub fn as_str(self) -> &'static str {
        match self {
            RangeStatus::RangeValid => "range valid",
            RangeStatus::SigmaFail => "sigma fail",
            RangeStatus::SignalFail => "signal fail",
            RangeStatus::RangeValidMinRangeClipped => "range valid, min range clipped",
            RangeStatus::OutOfBoundsFail => "out of bounds fail",
            RangeStatus::HardwareFail => "hardware fail",
            RangeStatus::RangeValidNoWrapCheckFail => "range valid, no wrap check fail",
            RangeStatus::WrapTargetFail => "wrap target fail",
            RangeStatus::XtalkSignalFail => "xtalk signal fail",
            RangeStatus::SynchronizationInt => "synchronization int",
            RangeStatus::MinRangeFail => "min range fail",
            RangeStatus::None => "no update",
        }
    }
}

#[derive(Debug, Clone, Copy)]
pub struct Measurement {
    pub range_mm: u16,
    pub status: RangeStatus,
    pub peak_signal_mcps: f32,
    pub ambient_mcps: f32,
}

impl Measurement {
    const EMPTY: Measurement = Measurement {
        range_mm: 0,
        status: RangeStatus::None,
        peak_signal_mcps: 0.0,
        ambient_mcps: 0.0,
    };
}

/// Stand-in for an XSHUT pin that isn't connected.
pub struct NoXshut;

impl PinErrorType for NoXshut {
    type Error = core::convert::Infallible;
}

impl OutputPin for NoXshut {
    fn set_low(&mut self) -> Result<(), Self::Error> {
        Ok(())
    }
    fn set_high(&mut self) -> Result<(), Self::Error> {
        Ok(())
    }
}

#[derive(Clone, Copy, Default)]
struct Results {
    range_status: u8,
    stream_count: u8,
    dss_actual_effective_spads_sd0: u16,
    ambient_count_rate_mcps_sd0: u16,
    final_crosstalk_corrected_range_mm_sd0: u16,
    peak_signal_count_rate_crosstalk_corrected_mcps_sd0: u16,
}

pub struct Vl53l1x<'a, I2C, X> {
    i2c: &'a mut I2C,
    xshut: X,
    address: u8,
    io_timeout: Option<Duration>,
    distance_mode: DistanceMode,
    fast_osc_frequency: u16,
    osc_calibrate_val: u16,
    calibrated: bool,
    saved_vhv_init: u8,
    saved_vhv_timeout: u8,
    results: Results,
    last: Measurement,
}

impl<'a, I2C, X> Vl53l1x<'a, I2C, X>
where
    I2C: I2c,
    X: OutputPin,
{
    /// Creates the driver. Nothing touches the bus until [`init`](Self::init).
    pub fn new(i2c: &'a mut I2C, xshut: X) -> Self {
        Self {
            i2c,
            xshut,
            address: DEFAULT_ADDRESS,
            io_timeout: Some(Duration::from_millis(500)),
            distance_mode: DistanceMode::Short,
            fast_osc_frequency: 0,
            osc_calibrate_val: 0,
            calibrated: false,
            saved_vhv_init: 0,
            saved_vhv_timeout: 0,
            results: Results::default(),
            last: Measurement::EMPTY,
        }
    }

    /// Timeout for the driver's own waits (boot, data-ready). `None` waits forever.
    pub fn set_timeout(&mut self, timeout: Option<Duration>) {
        self.io_timeout = timeout;
    }

    pub fn timeout(&self) -> Option<Duration> {
        self.io_timeout
    }

    pub fn distance_mode(&self) -> DistanceMode {
        self.distance_mode
    }

    /// Most recent measurement produced by `read`/`try_read`/`read_single`.
    pub fn last_measurement(&self) -> Measurement {
        self.last
    }

    // ---------------------------------------------------------------- init

    /// Resets the sensor (XSHUT toggle + soft reset) and loads the default
    /// low-power-autonomous configuration. `io_2v8` selects 2.8 V I/O mode
    /// (what most breakout boards want).
    /// timing budget is the amount of time the board has to measure, in short the min is 20ms, and
    /// medium and long its 33ms
    pub async fn init(
        &mut self,
        io_2v8: bool,
        mode: DistanceMode,
        timing_budget: u32,
    ) -> Res<(), I2C> {
        // Hardware reset via XSHUT (no-op with `NoXshut`).
        self.xshut.set_low().map_err(|_| Error::Pin)?;
        Timer::after_millis(10).await;
        self.xshut.set_high().map_err(|_| Error::Pin)?;
        Timer::after_millis(10).await;

        let id = self.read_u16(reg::IDENTIFICATION__MODEL_ID).await?;
        if id != MODEL_ID {
            return Err(Error::WrongDevice(id));
        }

        // VL53L1_software_reset()
        self.write_u8(reg::SOFT_RESET, 0x00).await?;
        Timer::after_micros(100).await;
        self.write_u8(reg::SOFT_RESET, 0x01).await?;
        Timer::after_millis(2).await;

        // VL53L1_poll_for_boot_completion(); NACKs while it boots are ignored.
        let start = Instant::now();
        loop {
            if let Ok(status) = self.read_u8(reg::FIRMWARE__SYSTEM_STATUS).await
                && status & 0x01 != 0
            {
                break;
            } else {
                self.check_timeout(start)?;
                Timer::after_millis(1).await;
            }
        }

        if io_2v8 {
            let v = self.read_u8(reg::PAD_I2C_HV__EXTSUP_CONFIG).await?;
            self.write_u8(reg::PAD_I2C_HV__EXTSUP_CONFIG, v | 0x01)
                .await?;
        }

        // Oscillator info, needed for all timing math.
        self.fast_osc_frequency = self
            .read_u16(reg::OSC_MEASURED__FAST_OSC__FREQUENCY)
            .await?;
        self.osc_calibrate_val = self.read_u16(reg::RESULT__OSC_CALIBRATE_VAL).await?;

        // Static config
        self.write_u16(reg::DSS_CONFIG__TARGET_TOTAL_RATE_MCPS, reg::Target_Rate)
            .await?;
        self.write_u8(reg::GPIO__TIO_HV_STATUS, 0x02).await?;
        self.write_u8(reg::SIGMA_ESTIMATOR__EFFECTIVE_PULSE_WIDTH_NS, 8)
            .await?;
        self.write_u8(reg::SIGMA_ESTIMATOR__EFFECTIVE_AMBIENT_WIDTH_NS, 16)
            .await?;

        self.write_u8(reg::ALGO__CROSSTALK_COMPENSATION_VALID_HEIGHT_MM, 0x01)
            .await?;
        self.write_u8(reg::ALGO__RANGE_IGNORE_VALID_HEIGHT_MM, 0xFF)
            .await?;
        self.write_u8(reg::ALGO__RANGE_MIN_CLIP, 0).await?;
        self.write_u8(reg::ALGO__CONSISTENCY_CHECK__TOLERANCE, 2)
            .await?;

        // General config
        self.write_u16(reg::SYSTEM__THRESH_RATE_HIGH, 0x0000)
            .await?;
        self.write_u16(reg::SYSTEM__THRESH_RATE_LOW, 0x0000).await?;
        self.write_u8(reg::DSS_CONFIG__APERTURE_ATTENUATION, 0x38)
            .await?;

        // Timing config (mostly overwritten by distance mode / timing budget)
        self.write_u16(reg::RANGE_CONFIG__SIGMA_THRESH, 360).await?;
        self.write_u16(reg::RANGE_CONFIG__MIN_COUNT_RATE_RTN_LIMIT_MCPS, 192)
            .await?;

        // Dynamic config
        self.write_u8(reg::SYSTEM__GROUPED_PARAMETER_HOLD_0, 0x01)
            .await?;
        self.write_u8(reg::SYSTEM__GROUPED_PARAMETER_HOLD_1, 0x01)
            .await?;
        self.write_u8(reg::SD_CONFIG__QUANTIFIER, 2).await?;

        self.write_u8(reg::SYSTEM__GROUPED_PARAMETER_HOLD, 0x00)
            .await?;
        self.write_u8(reg::SYSTEM__SEED_CONFIG, 1).await?;

        // VL53L1_config_low_power_auto_mode
        self.write_u8(reg::SYSTEM__SEQUENCE_CONFIG, 0x8B).await?; // VHV, PHASECAL, DSS1, RANGE
        self.write_u16(reg::DSS_CONFIG__MANUAL_EFFECTIVE_SPADS_SELECT, 200 << 8)
            .await?;
        self.write_u8(reg::DSS_CONFIG__ROI_MODE_CONTROL, 2).await?; // REQUESTED_EFFECTIVE_SPADS

        // Defaults: long range, 50 ms budget. (Registers are written directly
        // here; set_distance_mode() would first read back a budget from
        // registers that haven't been configured yet.)
        self.apply_distance_mode(mode).await?;
        self.set_measurement_timing_budget(timing_budget).await?;

        // The API does this once a measurement starts; assumes MM1/MM2 disabled.
        let offset = self.read_u16(reg::MM_CONFIG__OUTER_OFFSET_MM).await?;
        self.write_u16(
            reg::ALGO__PART_TO_PART_RANGE_OFFSET_MM,
            offset.wrapping_mul(4),
        )
        .await?;

        self.calibrated = false;
        Ok(())
    }

    /// Changes the sensor's I2C address (7-bit) until the next power cycle/reset.
    pub async fn set_address(&mut self, new_addr: u8) -> Res<(), I2C> {
        let new_addr = new_addr & 0x7F;
        self.write_u8(reg::I2C_SLAVE__DEVICE_ADDRESS, new_addr)
            .await?;
        self.address = new_addr;
        Ok(())
    }

    // ------------------------------------------------- distance / timing

    /// Sets the distance mode, keeping the current timing budget.
    pub async fn set_distance_mode(&mut self, mode: DistanceMode) -> Res<(), I2C> {
        let budget_us = self.measurement_timing_budget().await?;
        self.apply_distance_mode(mode).await?;
        self.set_measurement_timing_budget(budget_us).await
    }

    async fn apply_distance_mode(&mut self, mode: DistanceMode) -> Res<(), I2C> {
        let (period_a, period_b, phase_high, initial_phase): (u8, u8, u8, u8) = match mode {
            DistanceMode::Short => (0x07, 0x05, 0x38, 6),
            DistanceMode::Medium => (0x0B, 0x09, 0x78, 10),
            DistanceMode::Long => (0x0F, 0x0D, 0xB8, 14),
        };

        // Timing config
        self.write_u8(reg::RANGE_CONFIG__VCSEL_PERIOD_A, period_a)
            .await?;
        self.write_u8(reg::RANGE_CONFIG__VCSEL_PERIOD_B, period_b)
            .await?;
        self.write_u8(reg::RANGE_CONFIG__VALID_PHASE_HIGH, phase_high)
            .await?;

        // Dynamic config
        self.write_u8(reg::SD_CONFIG__WOI_SD0, period_a).await?;
        self.write_u8(reg::SD_CONFIG__WOI_SD1, period_b).await?;
        self.write_u8(reg::SD_CONFIG__INITIAL_PHASE_SD0, initial_phase)
            .await?;
        self.write_u8(reg::SD_CONFIG__INITIAL_PHASE_SD1, initial_phase)
            .await?;

        self.distance_mode = mode;
        Ok(())
    }
    fn min_timing_budget_us(mode: DistanceMode) -> u32 {
        match mode {
            DistanceMode::Short => 20_000,
            DistanceMode::Medium | DistanceMode::Long => 33_000,
        }
    }

    /// Sets the measurement timing budget in microseconds (longer = more
    /// accurate). Valid range is just above 4.5 ms up to 1.1 s; in continuous
    /// mode the inter-measurement period must be at least the budget.
    pub async fn set_measurement_timing_budget(&mut self, budget_us: u32) -> Res<(), I2C> {
        // Assumes LOWPOWER_AUTONOMOUS preset.
        let guard = reg::Timing_Guard;
        if budget_us <= guard {
            return Err(Error::InvalidArgument);
        }
        let mut range_timeout_us = budget_us - guard;
        if range_timeout_us > 1_100_000 {
            return Err(Error::InvalidArgument);
        }
        range_timeout_us /= 2;

        // Timing A (uses VCSEL period A)
        let vcsel_a = self.read_u8(reg::RANGE_CONFIG__VCSEL_PERIOD_A).await?;
        let macro_a = calc_macro_period(self.fast_osc_frequency, vcsel_a);

        // Phase calibration timeout (tuning default 1000 us), uses timing A.
        let phasecal_mclks = timeout_us_to_mclks(1000, macro_a).min(0xFF);
        self.write_u8(reg::PHASECAL_CONFIG__TIMEOUT_MACROP, phasecal_mclks as u8)
            .await?;

        // MM timing A: tuning default of 1 us.
        self.write_u16(
            reg::MM_CONFIG__TIMEOUT_MACROP_A,
            encode_timeout(timeout_us_to_mclks(1, macro_a)),
        )
        .await?;
        self.write_u16(
            reg::RANGE_CONFIG__TIMEOUT_MACROP_A,
            encode_timeout(timeout_us_to_mclks(range_timeout_us, macro_a)),
        )
        .await?;

        // Timing B (uses VCSEL period B)
        let vcsel_b = self.read_u8(reg::RANGE_CONFIG__VCSEL_PERIOD_B).await?;
        let macro_b = calc_macro_period(self.fast_osc_frequency, vcsel_b);

        // MM timing B: same 1 us default as A. (The fork passed the range
        // timeout here by mistake.)
        self.write_u16(
            reg::MM_CONFIG__TIMEOUT_MACROP_B,
            encode_timeout(timeout_us_to_mclks(1, macro_b)),
        )
        .await?;
        self.write_u16(
            reg::RANGE_CONFIG__TIMEOUT_MACROP_B,
            encode_timeout(timeout_us_to_mclks(range_timeout_us, macro_b)),
        )
        .await?;

        Ok(())
    }

    /// Current timing budget in microseconds.
    pub async fn measurement_timing_budget(&mut self) -> Res<u32, I2C> {
        // Assumes LOWPOWER_AUTONOMOUS with VHV, PHASECAL, DSS1, RANGE enabled.
        let vcsel_a = self.read_u8(reg::RANGE_CONFIG__VCSEL_PERIOD_A).await?;
        let macro_us = calc_macro_period(self.fast_osc_frequency, vcsel_a);

        let raw = self.read_u16(reg::RANGE_CONFIG__TIMEOUT_MACROP_A).await?;
        // mclks -> us. (The fork used the us -> mclks function here.)
        let range_timeout_us = timeout_mclks_to_us(decode_timeout(raw), macro_us);

        Ok(2 * range_timeout_us + reg::Timing_Guard)
    }

    // ------------------------------------------------------------- ROI

    /// Sets the region-of-interest size in SPADs (4..=16 each; ST's minimum is 4x4).
    pub async fn set_roi_size(&mut self, width: u8, height: u8) -> Res<(), I2C> {
        let width = width.clamp(4, 16);
        let height = height.clamp(4, 16);

        // Matches the ST ULD: large ROIs are forced to the centre.
        if width > 10 || height > 10 {
            self.write_u8(reg::ROI_CONFIG__USER_ROI_CENTRE_SPAD, 199)
                .await?;
        }
        self.write_u8(
            reg::ROI_CONFIG__USER_ROI_REQUESTED_GLOBAL_XY_SIZE,
            ((height - 1) << 4) | (width - 1),
        )
        .await
    }

    /// Returns `(width, height)` of the ROI.
    pub async fn roi_size(&mut self) -> Res<(u8, u8), I2C> {
        let v = self
            .read_u8(reg::ROI_CONFIG__USER_ROI_REQUESTED_GLOBAL_XY_SIZE)
            .await?;
        Ok(((v & 0x0F) + 1, (v >> 4) + 1))
    }

    /// Sets the ROI centre SPAD (199 is the default/centre). See ST UM2555 for
    /// the SPAD map; note the lens inverts the image.
    pub async fn set_roi_center(&mut self, spad: u8) -> Res<(), I2C> {
        self.write_u8(reg::ROI_CONFIG__USER_ROI_CENTRE_SPAD, spad)
            .await
    }

    pub async fn roi_center(&mut self) -> Res<u8, I2C> {
        self.read_u8(reg::ROI_CONFIG__USER_ROI_CENTRE_SPAD).await
    }

    // ------------------------------------------------------- ranging

    /// Starts continuous ranging with one measurement every `period_ms`.
    /// The period must be at least the timing budget.
    pub async fn start_continuous(&mut self, period_ms: u32) -> Res<(), I2C> {
        self.write_u32(
            reg::SYSTEM__INTERMEASUREMENT_PERIOD,
            period_ms.wrapping_mul(self.osc_calibrate_val as u32),
        )
        .await?;
        self.write_u8(reg::SYSTEM__INTERRUPT_CLEAR, 0x01).await?;
        self.write_u8(reg::SYSTEM__MODE_START, 0x40).await // mode_range__timed
    }

    pub async fn stop_continuous(&mut self) -> Res<(), I2C> {
        self.write_u8(reg::SYSTEM__MODE_START, 0x80).await?; // mode_range__abort
        self.calibrated = false;

        // Restore VHV configs and remove the phasecal override.
        if self.saved_vhv_init != 0 {
            self.write_u8(reg::VHV_CONFIG__INIT, self.saved_vhv_init)
                .await?;
        }
        if self.saved_vhv_timeout != 0 {
            self.write_u8(
                reg::VHV_CONFIG__TIMEOUT_MACROP_LOOP_BOUND,
                self.saved_vhv_timeout,
            )
            .await?;
        }
        self.write_u8(reg::PHASECAL_CONFIG__OVERRIDE, 0x00).await
    }

    /// True when a new measurement is waiting to be read.
    pub async fn data_ready(&mut self) -> Res<bool, I2C> {
        Ok(self.read_u8(reg::GPIO__TIO_HV_STATUS).await? & 0x01 == 0)
    }

    /// Non-blocking: returns `Some` if a fresh measurement was ready.
    pub async fn try_read(&mut self) -> Res<Option<Measurement>, I2C> {
        if !self.data_ready().await? {
            return Ok(None);
        }
        self.process_results().await.map(Some)
    }

    /// Waits (polling every millisecond, up to the IO timeout) for the next
    /// measurement and returns it. Use after `start_continuous`.
    pub async fn read(&mut self) -> Res<Measurement, I2C> {
        let start = Instant::now();
        while !self.data_ready().await? {
            self.check_timeout(start)?;
            Timer::after_millis(1).await;
        }
        self.process_results().await
    }

    /// Starts one measurement and waits for it.
    pub async fn read_single(&mut self) -> Res<Measurement, I2C> {
        self.write_u8(reg::SYSTEM__INTERRUPT_CLEAR, 0x01).await?;
        self.write_u8(reg::SYSTEM__MODE_START, 0x10).await?; // mode_range__single_shot
        self.read().await
    }

    async fn process_results(&mut self) -> Res<Measurement, I2C> {
        self.read_results().await?;

        if !self.calibrated {
            self.setup_manual_calibration().await?;
            self.calibrated = true;
        }

        self.update_dss().await?;
        let m = self.ranging_data();
        self.write_u8(reg::SYSTEM__INTERRUPT_CLEAR, 0x01).await?;

        self.last = m;
        Ok(m)
    }

    async fn read_results(&mut self) -> Res<(), I2C> {
        let mut b = [0u8; 17];
        self.i2c
            .write_read(
                self.address,
                &reg::RESULT__RANGE_STATUS.to_be_bytes(),
                &mut b,
            )
            .await
            .map_err(Error::I2c)?;

        self.results = Results {
            range_status: b[0],
            // b[1] report_status: unused
            stream_count: b[2],
            dss_actual_effective_spads_sd0: u16::from_be_bytes([b[3], b[4]]),
            // b[5..7] peak_signal_count_rate_mcps_sd0: unused
            ambient_count_rate_mcps_sd0: u16::from_be_bytes([b[7], b[8]]),
            // b[9..13] sigma_sd0, phase_sd0: unused
            final_crosstalk_corrected_range_mm_sd0: u16::from_be_bytes([b[13], b[14]]),
            peak_signal_count_rate_crosstalk_corrected_mcps_sd0: u16::from_be_bytes([b[15], b[16]]),
        };
        Ok(())
    }

    fn ranging_data(&self) -> Measurement {
        let r = &self.results;

        // Gain factor 2011 is the tuning default: scales by ~2011/2048 (with rounding).
        let range_mm =
            ((r.final_crosstalk_corrected_range_mm_sd0 as u32 * 2011 + 0x0400) / 0x0800) as u16;

        // Based on ConvertStatusLite() in the ST API.
        let status = match r.range_status {
            17 | 2 | 1 | 3 => RangeStatus::HardwareFail,
            13 => RangeStatus::MinRangeFail,
            18 => RangeStatus::SynchronizationInt,
            5 => RangeStatus::OutOfBoundsFail,
            4 => RangeStatus::SignalFail,
            6 => RangeStatus::SigmaFail,
            7 => RangeStatus::WrapTargetFail,
            12 => RangeStatus::XtalkSignalFail,
            8 => RangeStatus::RangeValidMinRangeClipped,
            9 => {
                if r.stream_count == 0 {
                    RangeStatus::RangeValidNoWrapCheckFail
                } else {
                    RangeStatus::RangeValid
                }
            }
            _ => RangeStatus::None,
        };

        Measurement {
            range_mm,
            status,
            // Count rates are 9.7 fixed point. f32: the ESP32 FPU is single precision.
            peak_signal_mcps: r.peak_signal_count_rate_crosstalk_corrected_mcps_sd0 as f32 / 128.0,
            ambient_mcps: r.ambient_count_rate_mcps_sd0 as f32 / 128.0,
        }
    }

    async fn update_dss(&mut self) -> Res<(), I2C> {
        let spad_count = self.results.dss_actual_effective_spads_sd0;

        if spad_count != 0 {
            // Total rate per SPAD, clipped to 16 bits.
            let mut total_rate_per_spad =
                self.results
                    .peak_signal_count_rate_crosstalk_corrected_mcps_sd0 as u32
                    + self.results.ambient_count_rate_mcps_sd0 as u32;
            if total_rate_per_spad > 0xFFFF {
                total_rate_per_spad = 0xFFFF;
            }
            // Shift up to use the full 32 bits.
            total_rate_per_spad <<= 16;
            total_rate_per_spad /= spad_count as u32;

            if total_rate_per_spad != 0 {
                let mut required_spads = ((reg::Target_Rate as u32) << 16) / total_rate_per_spad;
                if required_spads > 0xFFFF {
                    required_spads = 0xFFFF;
                }
                // DSS_CONFIG__ROI_MODE_CONTROL is already REQUESTED_EFFECTIVE_SPADS.
                return self
                    .write_u16(
                        reg::DSS_CONFIG__MANUAL_EFFECTIVE_SPADS_SELECT,
                        required_spads as u16,
                    )
                    .await;
            }
        }

        // Would have divided by zero: set the target to the mid point instead.
        self.write_u16(reg::DSS_CONFIG__MANUAL_EFFECTIVE_SPADS_SELECT, 0x8000)
            .await
    }

    async fn setup_manual_calibration(&mut self) -> Res<(), I2C> {
        // Save the original VHV configs.
        self.saved_vhv_init = self.read_u8(reg::VHV_CONFIG__INIT).await?;
        self.saved_vhv_timeout = self
            .read_u8(reg::VHV_CONFIG__TIMEOUT_MACROP_LOOP_BOUND)
            .await?;

        // Disable VHV init.
        self.write_u8(reg::VHV_CONFIG__INIT, self.saved_vhv_init & 0x7F)
            .await?;

        // Loop bound = tuning default (LOWPOWERAUTO_VHV_LOOP_BOUND_DEFAULT).
        self.write_u8(
            reg::VHV_CONFIG__TIMEOUT_MACROP_LOOP_BOUND,
            (self.saved_vhv_timeout & 0x03) + (3 << 2),
        )
        .await?;

        // Override phasecal.
        self.write_u8(reg::PHASECAL_CONFIG__OVERRIDE, 0x01).await?;
        let vcsel_start = self.read_u8(reg::PHASECAL_RESULT__VCSEL_START).await?;
        self.write_u8(reg::CAL_CONFIG__VCSEL_START, vcsel_start)
            .await
    }

    // --------------------------------------------------- bus helpers

    fn check_timeout(&self, start: Instant) -> Res<(), I2C> {
        match self.io_timeout {
            Some(limit) if start.elapsed() > limit => Err(Error::Timeout),
            _ => Ok(()),
        }
    }

    async fn write_u8(&mut self, register: u16, value: u8) -> Res<(), I2C> {
        let [hi, lo] = register.to_be_bytes();
        self.i2c
            .write(self.address, &[hi, lo, value])
            .await
            .map_err(Error::I2c)
    }

    async fn write_u16(&mut self, register: u16, value: u16) -> Res<(), I2C> {
        let [hi, lo] = register.to_be_bytes();
        let [vh, vl] = value.to_be_bytes();
        self.i2c
            .write(self.address, &[hi, lo, vh, vl])
            .await
            .map_err(Error::I2c)
    }

    async fn write_u32(&mut self, register: u16, value: u32) -> Res<(), I2C> {
        let [hi, lo] = register.to_be_bytes();
        let v = value.to_be_bytes();
        self.i2c
            .write(self.address, &[hi, lo, v[0], v[1], v[2], v[3]])
            .await
            .map_err(Error::I2c)
    }

    async fn read_u8(&mut self, register: u16) -> Res<u8, I2C> {
        let mut b = [0u8; 1];
        self.i2c
            .write_read(self.address, &register.to_be_bytes(), &mut b)
            .await
            .map_err(Error::I2c)?;
        Ok(b[0])
    }

    async fn read_u16(&mut self, register: u16) -> Res<u16, I2C> {
        let mut b = [0u8; 2];
        self.i2c
            .write_read(self.address, &register.to_be_bytes(), &mut b)
            .await
            .map_err(Error::I2c)?;
        Ok(u16::from_be_bytes(b))
    }
}

// ------------------------------------------------------ pure helpers
// These need no bus access, so they're plain functions (not async methods).

/// Macro period in microseconds (fixed point), from the oscillator frequency and VCSEL period.
fn calc_macro_period(fast_osc_frequency: u16, vcsel_period: u8) -> u32 {
    if fast_osc_frequency == 0 {
        return 0;
    }
    let pll_period_us = (1u32 << 30) / fast_osc_frequency as u32;
    let vcsel_period_pclks = (vcsel_period as u32 + 1) << 1;

    // Wrapping to match the C original's uint32_t arithmetic.
    let mut macro_period_us = 2304u32.wrapping_mul(pll_period_us);
    macro_period_us >>= 6;
    macro_period_us = macro_period_us.wrapping_mul(vcsel_period_pclks);
    macro_period_us >>= 6;
    macro_period_us
}

fn timeout_mclks_to_us(timeout_mclks: u32, macro_period_us: u32) -> u32 {
    (((timeout_mclks as u64) * (macro_period_us as u64) + 0x800) >> 12) as u32
}

fn timeout_us_to_mclks(timeout_us: u32, macro_period_us: u32) -> u32 {
    if macro_period_us == 0 {
        return 0;
    }
    let macro_period_us = macro_period_us as u64;
    ((((timeout_us as u64) << 12) + (macro_period_us >> 1)) / macro_period_us) as u32
}

/// Encoded format: `(LSByte * 2^MSByte) + 1`.
fn encode_timeout(timeout_mclks: u32) -> u16 {
    if timeout_mclks == 0 {
        return 0;
    }
    let mut ls_byte = timeout_mclks - 1;
    let mut ms_byte: u16 = 0;
    while ls_byte & 0xFFFF_FF00 > 0 {
        ls_byte >>= 1;
        ms_byte += 1;
    }
    (ms_byte << 8) | (ls_byte & 0xFF) as u16
}

fn decode_timeout(reg_val: u16) -> u32 {
    ((reg_val & 0xFF) as u32)
        .checked_shl((reg_val >> 8) as u32)
        .unwrap_or(u32::MAX)
        .saturating_add(1)
}
